// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IFirstContract {
    function activateTrading() external;
}

contract TradingHelper {
    address public immutable owner;
    IFirstContract public firstContract;

    constructor(address _firstContract) {
        owner = msg.sender;
        firstContract = IFirstContract(_firstContract);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    function forceEnableTrading() external onlyOwner {
        firstContract.activateTrading();
    }
}
